async function waitForPostgres(pool: pg.Pool) {
  const deadline = Date.now() + 15_000;
  while (Date.now() < deadline) {
    try {
      await pool.query("SELECT 1");
      return;
    } catch (error) {
      if (!(error instanceof Error && "code" in error && error.code === "ECONNREFUSED"))
        throw new Error("External PostgreSQL lab connection failed");
      await wait(100);
    }
  }
  throw new Error("WSL external PostgreSQL loopback forwarding deadline exceeded");
}

